dict(dia=25, kicker="Mitos tributários", tema="Mitos sobre recuperação tributária",
 sub="Frases repetidas não substituem análise.",
 slides=[
  ("*Mitos* sobre recuperação tributária", "Algumas frases circulam tanto que parecem verdade. Vamos separar o que merece cautela."),
  ("“Toda empresa tem crédito”", "Não. A existência de crédito depende da operação, do regime, do período e das regras aplicáveis a cada caso."),
  ("“Basta um sistema para encontrar valores”", "Ferramentas ajudam a organizar dados, mas a conclusão depende de análise técnica e de fundamento jurídico."),
  ("“Se a contabilidade não viu, estava errado”", "Divergência não prova erro. Muitas vezes, há explicações operacionais que precisam ser compreendidas primeiro."),
  ("“Recuperar é sempre rápido”", "Procedimentos podem envolver análise, processamento, exigências e acompanhamento. O tempo depende de cada situação."),
 ],
 leg_carrossel="“Toda empresa tem crédito”, “é só rodar um sistema”, “a contabilidade errou”, “o dinheiro volta rápido”. Essas frases aparecem com frequência em conversas e propostas comerciais. O problema é que elas simplificam uma avaliação que depende de operação, regime, período, documentos e regras aplicáveis. Qual dessas frases você já ouviu?",
 card=("Frase repetida *não substitui* análise tributária.", "Crédito, prazo e procedimento dependem do caso concreto."),
 leg_card="Quando uma frase pronta substitui a análise, a empresa decide com base em expectativa. Salve para lembrar na próxima proposta.",
 reels="Quatro frases que eu ouço sobre recuperação tributária",
 roteiro="Vou comentar quatro frases muito comuns. ‘Toda empresa tem crédito’: não necessariamente. Depende da operação e das regras. ‘É só passar num sistema’: ferramentas ajudam, mas não substituem análise técnica. ‘Se tem diferença, a contabilidade errou’: divergência pede explicação, não culpado. ‘O dinheiro volta rápido’: procedimentos têm etapas, exigências e acompanhamento. Não estou dizendo que recuperação não existe. Estou dizendo que ela precisa ser analisada, e não presumida.",
 leg_reels="Recuperação tributária existe, mas não é presumida. Depende de análise, fundamento e documentos. Envie para um empresário que já recebeu essas promessas.",
 stories=_st("Você já ouviu que toda empresa tem crédito tributário para recuperar?",
   ("DIDÁTICO", "Crédito depende de operação, regime, período, documentos e regras aplicáveis."),
   ("ENQUETE", "Qual frase você mais ouve? | Toda empresa tem crédito / O dinheiro volta rápido"),
   "No feed, comentei os quatro mitos mais comuns.")),

