dict(dia=28, kicker="Governança tributária", tema="Reunião tributária mensal",
 sub="Trinta minutos de alinhamento podem evitar meses de retrabalho.",
 slides=[
  ("Sua empresa tem uma *reunião tributária?*", "Um encontro curto e periódico entre gestão, financeiro, fiscal e contabilidade melhora a qualidade das decisões."),
  ("1. O que mudou na operação", "Novos produtos, clientes, unidades, contratos ou canais de venda. Toda mudança relevante deve ser comunicada."),
  ("2. O que chamou atenção nos números", "Variações nos tributos, divergências entre relatórios e dúvidas do fechamento entram na pauta."),
  ("3. O que mudou nas regras", "Atualizações legais e orientações oficiais que podem afetar a empresa, inclusive as etapas da reforma tributária."),
  ("4. Quem faz o quê e até quando", "Toda reunião termina com responsáveis e prazos definidos. Registre as decisões para consulta futura."),
 ],
 leg_carrossel="Muitas dúvidas tributárias surgem porque as áreas só conversam quando já existe um problema. Uma reunião mensal curta, com pauta fixa, ajuda a antecipar mudanças na operação, entender variações nos números, acompanhar atualizações legais e definir responsáveis. Não precisa ser longa; precisa ser constante. Salve a pauta e adapte à realidade da sua empresa.",
 card=("Trinta minutos de alinhamento *podem evitar* meses de retrabalho.", "Uma pauta fixa aproxima gestão, financeiro, fiscal e contabilidade."),
 leg_card="Governança tributária começa com comunicação regular entre as áreas. Compartilhe com o contador e o time financeiro.",
 reels="Uma reunião que pode mudar sua rotina tributária",
 roteiro="Se eu pudesse sugerir uma única prática para empresas de qualquer porte, seria esta: uma reunião tributária mensal. Curta, com pauta fixa. Primeiro, o que mudou na operação. Segundo, o que chamou atenção nos números. Terceiro, o que mudou nas regras. Quarto, quem faz o quê e até quando. Parece simples, mas evita que mudanças importantes fiquem sem comunicação e que dúvidas virem problemas acumulados.",
 leg_reels="Operação, números, regras e responsáveis: uma pauta simples para alinhar as áreas todo mês. Envie para quem organiza as reuniões da empresa.",
 stories=_st("Na sua empresa, as áreas conversam sobre tributos antes ou depois do problema?",
   ("CHECKLIST", "Pauta: operação, números, regras, responsáveis e prazos."),
   ("ENQUETE", "Vocês têm reunião periódica? | Sim / Só quando precisa"),
   "No feed, deixei uma pauta pronta para usar.")),

